options(stringsAsFactors=FALSE,warn=1)
suppressPackageStartupMessages({library(dplyr);library(tidyr)})
set.seed(20260815)
project<-normalizePath(getwd(),winslash="/",mustWork=TRUE);dd<-file.path(project,"data","causal_landmark");od<-file.path(project,"results","causal_landmark");td<-file.path(project,"tables","causal_landmark");ld<-file.path(project,"logs","causal_landmark")
d<-readRDS(file.path(dd,"landmark_long_no_outcomes_internal_restricted.rds"));elig<-readRDS(file.path(dd,"landmark_eligible_ids_internal_restricted.rds"))
h<-d%>%filter(wave<=2004,!is.na(fuel_state))%>%arrange(Idind,wave)%>%group_by(Idind)%>%mutate(score=case_when(fuel_state=="solid_only"~1,fuel_state=="mixed"~.5,TRUE~0),next_wave=lead(wave,default=2004),duration=pmax(next_wave-wave,0),transition=as.integer(fuel_state!=lag(fuel_state)),clean_to_mixed=as.integer(lag(fuel_state)=="clean_only"&fuel_state=="mixed"),mixed_to_solid=as.integer(lag(fuel_state)=="mixed"&fuel_state=="solid_only"))%>%summarise(previous_fuel_state=last(fuel_state),number_prior_fuel_waves=n(),proportion_prior_solid_only=mean(fuel_state=="solid_only"),proportion_prior_mixed=mean(fuel_state=="mixed"),proportion_prior_clean_only=mean(fuel_state=="clean_only"),proportion_prior_any_solid=mean(fuel_state%in%c("solid_only","mixed")),ever_clean_before_2006=as.integer(any(fuel_state=="clean_only")),ever_mixed_before_2006=as.integer(any(fuel_state=="mixed")),number_fuel_transitions=sum(transition,na.rm=TRUE),number_clean_to_mixed_reversals=sum(clean_to_mixed,na.rm=TRUE),number_mixed_to_solid_reversals=sum(mixed_to_solid,na.rm=TRUE),years_since_first_clean_observation=ifelse(any(fuel_state=="clean_only"),2006-min(wave[fuel_state=="clean_only"]),NA_real_),duration_weighted_solid_equivalent_history_to_2004=ifelse(sum(duration)>0,sum(score*duration)/sum(duration),mean(score)),last_two_wave_pattern=ifelse(n()>=2,paste(tail(fuel_state,2),collapse=" -> "),as.character(last(fuel_state))),.groups="drop")
recent<-d%>%filter(wave<=2004)%>%arrange(Idind,wave)%>%group_by(Idind)%>%summarise(age2004=last(age[!is.na(age)]),sex=last(sex[!is.na(sex)]),province=last(province[!is.na(province)]),commid2004=last(commid[!is.na(commid)]),urban_recent=ifelse(any(!is.na(urban)),last(urban[!is.na(urban)]),NA),education_recent=ifelse(any(!is.na(education_years)),last(education_years[!is.na(education_years)]),NA),income_recent=ifelse(any(!is.na(income_asinh)),last(income_asinh[!is.na(income_asinh)]),NA),income_mean=mean(income_asinh,na.rm=TRUE),income_change=ifelse(sum(!is.na(income_asinh))>=2,last(income_asinh[!is.na(income_asinh)])-first(income_asinh[!is.na(income_asinh)]),NA),assets_recent=ifelse(any(!is.na(asset_count)),last(asset_count[!is.na(asset_count)]),NA),assets_mean=mean(asset_count,na.rm=TRUE),assets_change=ifelse(sum(!is.na(asset_count))>=2,last(asset_count[!is.na(asset_count)])-first(asset_count[!is.na(asset_count)]),NA),smoking_recent=ifelse(any(!is.na(smoking)),last(smoking[!is.na(smoking)]),NA),alcohol_recent=ifelse(any(!is.na(alcohol)),last(alcohol[!is.na(alcohol)]),NA),.groups="drop")%>%mutate(across(c(income_mean,assets_mean),~ifelse(is.nan(.x),NA,.x)))
post<-d%>%filter(wave==2009)%>%select(Idind,fuel2009=fuel_state,biomarker2009)%>%distinct()
lm<-elig%>%select(Idind,A,treatment,fuel2004,fuel2006,biomarker2009)%>%left_join(h,by="Idind")%>%left_join(recent,by="Idind")%>%left_join(post%>%select(-biomarker2009),by="Idind")%>%mutate(sex=factor(sex),province=factor(province),fuel2004=factor(fuel2004),previous_fuel_state=factor(previous_fuel_state),last_two_wave_pattern=factor(last_two_wave_pattern))
saveRDS(lm,file.path(dd,"landmark_analysis_no_outcomes_internal_restricted.rds"),compress="gzip")
defs<-data.frame(variable=c("previous_fuel_state","number_prior_fuel_waves","proportion_prior_solid_only","proportion_prior_mixed","proportion_prior_clean_only","proportion_prior_any_solid","ever_clean_before_2006","ever_mixed_before_2006","number_fuel_transitions","number_clean_to_mixed_reversals","number_mixed_to_solid_reversals","years_since_first_clean_observation","duration_weighted_solid_equivalent_history_to_2004","last_two_wave_pattern"),window="1989-2004 only",definition=c("last valid state by 2004","count valid fuel waves","fraction solid-only","fraction mixed","fraction clean-only","fraction solid-only or mixed","any clean-only","any mixed","count adjacent state changes","count clean-to-mixed","count mixed-to-solid","2006 minus first clean year; missing if never clean","interval-weighted operational score: solid=1,mixed=.5,clean=0","two most recent valid states"))
write.csv(defs,file.path(td,"Table_pretreatment_history_definitions.csv"),row.names=FALSE)
audit<-data.frame(variable=names(lm),source_variable=names(lm),wave=ifelse(grepl("fuel|prior|history|transition|reversal",names(lm)),"1989-2004","most recent <=2004"),pretreatment_status=ifelse(names(lm)%in%c("fuel2006","A","treatment","fuel2009","biomarker2009"),"treatment/post-treatment/selection","pretreatment"),role=ifelse(names(lm)%in%c("fuel2006","A","treatment"),"treatment",ifelse(names(lm)%in%c("fuel2009"),"post-treatment descriptive",ifelse(names(lm)%in%c("biomarker2009"),"selection","candidate confounder"))),missingness=vapply(lm,function(x)mean(is.na(x)),numeric(1)),included_primary_model=FALSE,reason="final selection in weighting script")
write.csv(audit,file.path(td,"Table_landmark_covariate_audit.csv"),row.names=FALSE);writeLines("LANDMARK_HISTORY=PASS",file.path(ld,"02_landmark_history_features.log"),useBytes=TRUE)

